import fs from 'fs';
import os from 'os';
import path from 'path';

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

// Real .env files, as for WEBHOOK_PORT: the service unit is regenerated by
// setup, so .env is the only durable place an operator can set this.
describe('NANOCLAW_TEMPLATES_DIR configuration', () => {
  const originalCwd = process.cwd();
  let directory: string;

  beforeEach(() => {
    directory = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), 'nanoclaw-templates-dir-')));
    process.chdir(directory);
    vi.stubEnv('NANOCLAW_TEMPLATES_DIR', undefined);
    vi.resetModules();
  });

  afterEach(() => {
    process.chdir(originalCwd);
    vi.unstubAllEnvs();
    fs.rmSync(directory, { recursive: true, force: true });
  });

  it('reads the directory from .env without populating process.env', async () => {
    fs.writeFileSync(path.join(directory, '.env'), 'NANOCLAW_TEMPLATES_DIR=/srv/agent-templates\n');
    const { TEMPLATES_DIR } = await import('./config.js');

    expect(TEMPLATES_DIR).toBe('/srv/agent-templates');
    expect(process.env.NANOCLAW_TEMPLATES_DIR).toBeUndefined();
  });

  it('lets the process environment override .env', async () => {
    fs.writeFileSync(path.join(directory, '.env'), 'NANOCLAW_TEMPLATES_DIR=/srv/agent-templates\n');
    vi.stubEnv('NANOCLAW_TEMPLATES_DIR', '/opt/other-templates');
    const { TEMPLATES_DIR } = await import('./config.js');

    expect(TEMPLATES_DIR).toBe('/opt/other-templates');
  });

  it('defaults to templates/ under the project root when neither source sets it', async () => {
    const { TEMPLATES_DIR } = await import('./config.js');

    expect(TEMPLATES_DIR).toBe(path.join(directory, 'templates'));
  });
});
